@page "/apply"
@using sv_90296aff4d184f6ba7f58204bd22734a.Components.Pages.Apply
@using sv_90296aff4d184f6ba7f58204bd22734a.Models
@rendermode InteractiveServer

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="mb-4 text-center">Job Application</h2>

    <StepIndicator CurrentStep="_currentStep" OnNavigate="GoToStep" />

    @switch (_currentStep)
    {
        case 0:
            <PersonalInfoStep Model="_personal"
                              ValidateEmail="AppService.ValidateEmailAsync"
                              OnNext="NextStep" />
            break;
        case 1:
            <WorkHistoryStep Entries="_workEntries"
                             OnNext="NextStep"
                             OnBack="PreviousStep" />
            break;
        case 2:
            <ReferencesStep References="_references"
                            OnNext="NextStep"
                            OnBack="PreviousStep" />
            break;
        case 3:
            <CoverLetterStep @bind-CoverLetter="_coverLetter"
                             OnNext="NextStep"
                             OnBack="PreviousStep" />
            break;
        case 4:
            <ReviewStep Personal="_personal"
                        WorkEntries="_workEntries"
                        References="_references"
                        CoverLetter="_coverLetter"
                        OnBack="PreviousStep"
                        OnEditStep="GoToStep"
                        OnSubmit="SubmitAsync" />
            break;
    }
</div>

@code {
    [Inject] private IApplicationService AppService { get; set; } = default!;

    private int _currentStep;
    private PersonalInfoModel _personal = new();
    private List<WorkEntryModel> _workEntries = new() { new() };
    private List<ReferenceModel> _references = new() { new(), new() };
    private string _coverLetter = "";

    private void NextStep() => _currentStep++;
    private void PreviousStep() => _currentStep--;
    private void GoToStep(int step) => _currentStep = step;

    private async Task<int> SubmitAsync()
    {
        var application = new JobApplication(
            _personal.ToRecord(),
            new WorkHistory(_workEntries.Select(e => e.ToRecord()).ToList()),
            _references.Select(r => r.ToRecord()).ToList(),
            _coverLetter
        );

        return await AppService.SubmitApplicationAsync(application);
    }
}

::deep .step-indicator .step-circle {
    width: 36px;
    height: 36px;
    font-size: 0.9rem;
    transition: all 0.2s ease;
}

::deep .step-indicator .step-item.completed {
    cursor: pointer;
}

::deep .step-indicator .step-item.upcoming {
    cursor: default;
    opacity: 0.5;
}

::deep .step-indicator .step-item.current {
    cursor: default;
}

